// The one place that knows what the lab's mail looks like - adjust it when you have
// the first real mail in front of you (Executions -> this node -> Input).
//
// Everything downstream only needs { orderId, downloadUrl }:
//  - orderId    the lab's order number, which matches Roll.labOrderId in filmnotes
//  - downloadUrl a link the CLI can GET; it may point at a zip without a .zip in the URL
const item = $input.first().json;
const text = [item.textPlain, item.textHtml, item.subject].filter(Boolean).join('\n');

// dm/CEWE print a 12-digit order number on the receipt; the mail carries it as
// `orderID=540996-624893` or in plain text. Both forms are accepted, the first part wins.
const orderMatch = /order(?:ID|nummer|number)?[=:\s]*([0-9]{5,14})/i.exec(text);
const orderId = orderMatch?.[1] ?? null;

// Any https link that looks like a download rather than a marketing link.
const urls = [...text.matchAll(/https?:\/\/[^\s"'<>)]+/gi)].map((match) => match[0]);
const downloadUrl =
  urls.find((url) => /download|digital|bilder|images|zip/i.test(url)) ?? null;

return [{ json: { orderId, downloadUrl, subject: item.subject ?? '', urls } }];

// `--json` prints exactly one line: { uploaded, skipped, failed, files, dryRun }.
const { stdout = '', stderr = '', exitCode } = $input.first().json;
const line = stdout.trim().split('\n').filter(Boolean).pop() ?? '{}';

let result = {};
try {
  result = JSON.parse(line);
} catch {
  // Keep going: the mail below is more useful with the raw output than with an exception.
  result = { uploaded: 0, failed: [], files: 0, parseError: line.slice(0, 500) };
}

const roll = $('PocketBase: roll for this order').first().json.items[0];
return [
  {
    json: {
      ...result,
      exitCode,
      stderr: stderr.slice(0, 2000),
      rollId: roll.id,
      orderId: roll.labOrderId,
    },
  },
];

