// One item per roll, so the HTTP node below asks the lab about one order at a time.
return ($input.first().json.items ?? []).map((roll) => ({
  json: { rollId: roll.id, orderId: roll.labOrderId, status: roll.status },
}));

// The second place that knows about the lab - adjust once you have seen one real answer
// (Executions -> 'Lab: order info' -> Output). Everything below only needs { finished, label }.
const info = $input.first().json;
const roll = $('One roll at a time').first().json;

// Defensive: the field names are not documented, so anything that looks like a state is read.
const state = String(
  info.orderState ?? info.state ?? info.status ?? info.orderStatus ?? '',
).toLowerCase();
const finished = /fertig|abgeschlossen|versand|shipped|complete|done|ready/.test(state);

return [
  {
    json: {
      ...roll,
      finished,
      label: state === '' ? JSON.stringify(info).slice(0, 300) : state,
    },
  },
];

